	@Test
	void rejectsConfiguredDiskBudget() throws Exception {
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		RDFJSONWriter writer = new RDFJSONWriter(output, RDFFormat.RDFJSON);
		writer.getWriterConfig().set(RDFJSONWriterSettings.MAX_IN_MEMORY_BYTES, 128L);
		writer.getWriterConfig().set(RDFJSONWriterSettings.MAX_SPILL_BYTES, 256L);
		ValueFactory factory = SimpleValueFactory.getInstance();
		writer.startRDF();

		RDFHandlerException failure = assertThrows(RDFHandlerException.class, () -> {
			writer.handleStatement(factory.createStatement(factory.createIRI("urn:test:subject"),
					factory.createIRI("urn:test:predicate"), factory.createLiteral("x".repeat(2048))));
			writer.endRDF();
		});
		assertTrue(failure.getMessage().contains("RDF/JSON temporary disk budget exceeded"));
		Statement smaller = factory.createStatement(factory.createIRI("urn:s"), factory.createIRI("urn:p"),
				factory.createLiteral("x".repeat(32)));
		assertEquals(legacyOutput(List.of(smaller), false), boundedOutput(List.of(smaller), false, 128L, 256L));
	}

	@Test
	void unsupportedDeepTripleTermFailsCleanlyWhenEncodingIsDisabled() {
		ValueFactory factory = SimpleValueFactory.getInstance();
		IRI subject = factory.createIRI("urn:test:subject");
		IRI predicate = factory.createIRI("urn:test:predicate");
		Value object = factory.createLiteral("leaf");
		for (int i = 0; i < 2_000; i++) {
			object = factory.createTripleTerm(subject, predicate, object);
		}
		Statement statement = factory.createStatement(subject, predicate, object);
		for (boolean streaming : new boolean[] { false, true }) {
			RDFJSONWriter writer = new RDFJSONWriter(new StringWriter(), RDFFormat.RDFJSON);
			writer.getWriterConfig().set(BasicWriterSettings.ENCODE_TRIPLE_TERMS, false);
			writer.getWriterConfig().set(RDFJSONWriterSettings.ALLOW_MULTIPLE_OBJECT_VALUES, streaming);
			writer.getWriterConfig().set(RDFJSONWriterSettings.MAX_IN_MEMORY_BYTES, 128L);
			RDFHandlerException failure = assertThrows(RDFHandlerException.class, () -> {
				writer.startRDF();
				writer.handleStatement(statement);
				writer.endRDF();
			});
			assertTrue(failure.getMessage().contains("does not support triple terms"));
		}
	}

