	@Test
	void spillFilesAreRemovedOnSuccessAndFailure() throws Exception {
		ValueFactory vf = SimpleValueFactory.getInstance();
		Statement first = vf.createStatement(vf.createIRI("urn:test:s"), vf.createIRI("urn:test:p"),
				vf.createLiteral("x".repeat(80)));
		Statement second = vf.createStatement(vf.createIRI("urn:test:s"), vf.createIRI("urn:test:p"),
				vf.createLiteral("y".repeat(80)));
		try (RDFJSONStatementSpool spool = new RDFJSONStatementSpool(128L, 400L, tempDirectory)) {
			spool.add(first);
			assertEquals(1, fileCount(tempDirectory));
			assertThrows(IOException.class, () -> spool.add(second));
		}
		assertEquals(0, fileCount(tempDirectory));
		try (RDFJSONStatementSpool spool = new RDFJSONStatementSpool(128L, 1024L, tempDirectory)) {
			spool.add(first);
			spool.add(second);
			try (RDFJSONStatementSpool.SortedStatements sorted = spool.sortedStatements()) {
				assertEquals(2, List.of(sorted.next(), sorted.next()).size());
			}
		}
		assertEquals(0, fileCount(tempDirectory));
	}

